insert into public.vocabulary_items
(vocabulary_id,term,part_of_speech,core_meaning,senses,word_family,collocations,status)
values
('vocab_active','active','adjective','taking a full part in something, rather than only watching or receiving information','[{"senseId":"active_1","meaning":"taking a full part in something, rather than only watching or receiving information","acceptedParaphrases":["fully involved","taking a real part"],"masteryContexts":[{"contextId":"u6_11_active_meaning","text":"Students who play an active part in group discussions usually understand the topic better than those who stay silent.","meaning":"fully involved and taking part","wrongMeanings":["full of physical energy and movement","busy with too many different jobs","quick to give an answer"]},{"contextId":"u6_11_active_paraphrase","text":"The museum gives children the chance to be active learners by building models instead of just reading labels.","meaning":"doing things rather than only receiving information","wrongMeanings":["always moving about the classroom","busy at every hour of the day","strong enough to lift heavy objects"]}],"situationDistractors":["The pupil sat at the back with her arms folded and waited for the lesson to finish.","After the long journey, the family slept in the hotel until late in the morning.","The manager read the report from the first page to the last and filed it without comment.","The caretaker unlocked the gate and switched on the lights in the corridor.","Tom copied the date from the board and then looked out of the window for the rest of the lesson.","After lunch, the visitors rested in the garden and drank tea."],"gapDistractors":[{"contextId":"u6_11_active_gap_1","answer":"active","wrong":["absent","nervous","generous"]},{"contextId":"u6_11_active_gap_2","answer":"active","wrong":["unusual","optional","official"]},{"contextId":"u6_11_active_gap_3","answer":"active","wrong":["untidy","anxious","impatient"]}],"spellingErrors":["activ","acitve","actve","aktive","activee","actieve"],"wordFamilyForms":[{"form":"active","partOfSpeech":"adjective","example":"Students who are active in lessons tend to remember more of what they learn.","pedagogicallyUseful":true},{"form":"activity","partOfSpeech":"noun","example":"The teacher planned a short speaking activity to end the lesson.","pedagogicallyUseful":true,"altExample":"Writing a short summary is a useful activity to do at the end of every lesson."},{"form":"actively","partOfSpeech":"adverb","example":"Students learn best when they actively take part in the lesson.","pedagogicallyUseful":true,"altExample":"Employees who actively ask questions in training sessions learn new systems faster."}],"masteryPassages":[{"passageId":"u6_11_active_passage_1","contextId":"u6_11_active_gap_1","text":"Some museums no longer ask visitors to walk quietly past glass cases. Instead, they invite children to build, test and ask questions, because learners who are ____ remember far more than those who simply look and listen.","answer":"active"},{"passageId":"u6_11_active_passage_2","contextId":"u6_11_active_gap_2","text":"The teacher noticed that the same few students answered every question. She changed the lesson so that each pupil had a task, and soon even the quietest members of the class became ____ participants.","answer":"active"}],"contextDependentParaphrases":[],"wrongParaphrases":["always busy with chores","quick to learn new skills","ready to give advice"],"misleadingDistractors":["full of physical energy and always moving","busy with several tasks at the same time","quick to give an answer in class"],"teacherNote":"Taught in its learning sense: taking a full part and doing things, instead of only receiving information. It is the opposite of passive. It does not mean physically energetic (an active child) or busy (an active week)."}]'::jsonb,'["activity","actively"]'::jsonb,'["an active role","active learner","take an active part"]'::jsonb,'live'),
('vocab_evaluate_6','evaluate','verb','to judge the quality, value or effectiveness of something by using evidence or clear criteria','[{"senseId":"evaluate_6_1","meaning":"to judge the quality, value or effectiveness of something by using evidence or clear criteria","acceptedParaphrases":["judge the quality of","measure how well it works"],"masteryContexts":[{"contextId":"u6_12_evaluate_6_meaning","text":"Marine biologists evaluate each conservation project by comparing fish numbers before and after the work began.","meaning":"to judge how successful something is using evidence","wrongMeanings":["to describe how something looks in detail","to make something larger after the work ends","to give a prize to the best project"]},{"contextId":"u6_12_evaluate_6_paraphrase","text":"In the final task, candidates must describe two study methods and then evaluate which one suits them better.","meaning":"to judge the value of something by giving reasons","wrongMeanings":["to describe two methods without an opinion","to copy a method from another student","to choose a method at random"]}],"situationDistractors":["The reporter listed the names of the winners and the prizes they received.","A student typed out the speech word for word and read it aloud to the class.","Rain delayed the match, and the players waited in the changing room.","The guide pointed to the old clock tower and told the group when it was built.","The students copied the diagram from the board into their books.","Heavy snow closed the road, so the bus did not run."],"gapDistractors":[{"contextId":"u6_12_evaluate_6_gap_1","answer":"evaluate","wrong":["announce","invent","advertise"]},{"contextId":"u6_12_evaluate_6_gap_2","answer":"evaluate","wrong":["ignore","forget","delete"]},{"contextId":"u6_12_evaluate_6_gap_3","answer":"evaluate","wrong":["ignore","neglect","hide"]}],"spellingErrors":["evalute","evaluat","evalaute","evaluete","evluate","evalueate"],"masteryPassages":[{"passageId":"u6_12_evaluate_6_passage_1","contextId":"u6_12_evaluate_6_gap_1","text":"Describing a new app is easy: you say what it looks like and what it can do. The harder skill is to ____ it, by deciding how useful it is and giving evidence to support your judgement.","answer":"evaluate"},{"passageId":"u6_12_evaluate_6_passage_2","contextId":"u6_12_evaluate_6_gap_2","text":"A small company tested two training programmes with its new staff. After six months, managers looked at test scores and customer comments in order to ____ which programme had worked better.","answer":"evaluate"}],"contextDependentParaphrases":[],"wrongParaphrases":["write a summary of","make a copy of","give a prize for"],"misleadingDistractors":["to describe something in detail without giving an opinion","to repeat something until it is remembered","to copy something so that it looks the same"],"teacherNote":"Unit 6 item (evaluate_6), separate from the Unit 3 and Unit 5 evaluate items; shares only the lexical spelling list. Sense: to judge quality, value or effectiveness using evidence or criteria. It is not the same as describe, which only says what something is like."}]'::jsonb,'[]'::jsonb,'["evaluate the evidence","evaluate the success of","carefully evaluate"]'::jsonb,'live'),
('vocab_reflect','reflect','verb','to think carefully about an experience, action or idea, especially in order to learn from it','[{"senseId":"reflect_1","meaning":"to think carefully about an experience, action or idea, especially in order to learn from it","acceptedParaphrases":["think back carefully","look back and learn"],"masteryContexts":[{"contextId":"u6_13_reflect_meaning","text":"After the group project, the teacher gave everyone ten minutes to reflect on what had gone well and what had not.","meaning":"to think carefully about an experience in order to learn from it","wrongMeanings":["to repeat the same task until it is perfect","to complain about the task to the teacher","to forget a mistake as quickly as possible"]},{"contextId":"u6_13_reflect_paraphrase","text":"Many successful athletes keep a diary so that they can reflect on each match and improve their next performance.","meaning":"to think carefully about past actions in order to improve","wrongMeanings":["to watch a recording of the match again for fun","to show a mistake to the rest of the team","to copy the best player on the team"]}],"situationDistractors":["The pupils lined up at the door and followed the teacher to the canteen.","A student crossed out his answer, wrote another one and handed in the paper at once.","The coach shouted instructions from the side of the pitch while the players ran up and down.","The mechanic opened the bonnet and changed the oil in the engine.","Two pupils shared a book because there were not enough copies for the class.","The team celebrated loudly and then headed to the restaurant."],"gapDistractors":[{"contextId":"u6_13_reflect_gap_1","answer":"reflect","wrong":["insist","agree","vote"]},{"contextId":"u6_13_reflect_gap_2","answer":"reflect","wrong":["rely","agree","insist"]},{"contextId":"u6_13_reflect_gap_3","answer":"reflect","wrong":["depend","rely","agree"]}],"spellingErrors":["reflet","reflact","relfect","reflecct","refelct","reflekt"],"wordFamilyForms":[{"form":"reflect","partOfSpeech":"verb","example":"Teachers often ask students to reflect on their progress at the end of a project.","pedagogicallyUseful":true},{"form":"reflection","partOfSpeech":"noun","example":"Time for quiet reflection helps learners to understand what they have done well.","pedagogicallyUseful":true,"altExample":"Her reflection on the first term helped her to choose a better study plan."},{"form":"reflective","partOfSpeech":"adjective","example":"Teachers encourage students to become reflective learners by keeping a weekly diary.","pedagogicallyUseful":true,"altExample":"A reflective student asks why a method worked, not just whether it worked."}],"masteryPassages":[{"passageId":"u6_13_reflect_passage_1","contextId":"u6_13_reflect_gap_1","text":"At the end of each week, the swimming coach gives her team ten minutes without talking. During that time, the swimmers ____ on their training, thinking about what they did well and what they could change.","answer":"reflect"},{"passageId":"u6_13_reflect_passage_2","contextId":"u6_13_reflect_gap_2","text":"Students often hurry from one task to the next and learn little from their mistakes. A short learning journal gives them a regular chance to ____ on what went wrong and how to avoid the same problem again.","answer":"reflect"}],"contextDependentParaphrases":[],"wrongParaphrases":["rush through each task","copy a friend’s answer","argue about the marks"],"misleadingDistractors":["to repeat information until it is remembered","to copy another person’s ideas exactly","to hurry through a task to finish quickly"],"teacherNote":"Taught in its thinking sense: to think carefully about an experience, action or idea, especially in order to learn from it (reflect on a mistake). The mirror and light senses are not taught. It is usually followed by on."}]'::jsonb,'["reflection","reflective"]'::jsonb,'["reflect on your progress","reflect on an experience","reflect carefully"]'::jsonb,'live'),
('vocab_process','process','verb','to think about new information until you can make sense of it','[{"senseId":"process_1","meaning":"to think about new information until you can make sense of it","acceptedParaphrases":["make sense of","sort out and understand"],"masteryContexts":[{"contextId":"u6_14_process_meaning","text":"Teenagers sometimes need a quiet room to process difficult news before they can talk about it.","meaning":"to think about something until you can make sense of it","wrongMeanings":["to hide something from other people","to repeat something to a friend","to write something down quickly"]},{"contextId":"u6_14_process_paraphrase","text":"Language learners process spoken words faster when they hear them in a clear and familiar context.","meaning":"to work through information until you understand it","wrongMeanings":["to produce information in a factory","to copy information onto paper","to store information in a file"]}],"situationDistractors":["The workers loaded boxes onto the lorry and drove them to the warehouse.","The librarian stacked the returned books on the trolley and wheeled it to the shelves.","Leo wrote his name at the top of the page and sharpened three pencils.","The farmer sold his vegetables at the market every Saturday.","A student wrote the answers on a small card and hid it inside his sleeve.","The school bus stopped outside the gate at a quarter to eight."],"gapDistractors":[{"contextId":"u6_14_process_gap_1","answer":"process","wrong":["produce","invent","forget"]},{"contextId":"u6_14_process_gap_2","answer":"process","wrong":["copy","skip","print"]},{"contextId":"u6_14_process_gap_3","answer":"process","wrong":["ignore","cancel","shorten"]}],"spellingErrors":["proces","procces","prosess","proccess","processs","procass"],"masteryPassages":[{"passageId":"u6_14_process_passage_1","contextId":"u6_14_process_gap_1","text":"After listening to a long lecture, many students feel tired, because the brain has to ____ a great deal of new information at the same time. Short breaks allow it to sort ideas into a clear order.","answer":"process"},{"passageId":"u6_14_process_passage_2","contextId":"u6_14_process_gap_2","text":"Young children need time to ____ what they hear. A teacher who asks a question and waits patiently for a few seconds usually gets a better answer than one who moves on immediately.","answer":"process"}],"contextDependentParaphrases":[],"wrongParaphrases":["hand in a copy of","argue about the value of","keep a record of"],"misleadingDistractors":["to collect information from many different places","to repeat information aloud to other people","to hide information so that nobody can find it"],"teacherNote":"Taught as a verb in its learning sense: to think about new information until you can make sense of it (process new information). Boundary: absorb is taking information in, process is working on it in your mind, retain is keeping it, memorise is learning it exactly. The factory sense (to process food) and the noun sense (a process) are not taught here."}]'::jsonb,'[]'::jsonb,'["process information","process new ideas","process what you hear"]'::jsonb,'live'),
('vocab_strategy','strategy','noun','a carefully planned method for achieving a goal','[{"senseId":"strategy_1","meaning":"a carefully planned method for achieving a goal","acceptedParaphrases":["carefully planned method","plan for reaching a goal"],"masteryContexts":[{"contextId":"u6_15_strategy_meaning","text":"The football manager changed his strategy at half-time and put an extra player in defence.","meaning":"a plan for reaching a goal","wrongMeanings":["a rule that players must obey","a trophy given to the winning team","a mistake made by the defence"]},{"contextId":"u6_15_strategy_paraphrase","text":"Our class developed a strategy for learning irregular verbs: we grouped them by sound and tested each other every week.","meaning":"a planned method for achieving a goal","wrongMeanings":["a long list of difficult words","a game that helps students to relax","a test taken at the end of the week"]}],"situationDistractors":["He grabbed the nearest book from the shelf and started reading it without a plan.","The architect drew the window and the door on the same sheet of paper.","A man waved at the bus driver and jumped on just before the doors closed.","The little boy waved goodbye to his grandmother from the window of the train.","Ana lost her keys, searched every pocket and eventually found them in the kitchen.","The shop closed at six, so the customers left one by one."],"gapDistractors":[{"contextId":"u6_15_strategy_gap_1","answer":"strategy","wrong":["mistake","accident","rumour"]},{"contextId":"u6_15_strategy_gap_2","answer":"strategy","wrong":["accident","celebration","complaint"]},{"contextId":"u6_15_strategy_gap_3","answer":"strategy","wrong":["colour","distance","accident"]}],"spellingErrors":["stratagy","stratergy","strategi","stradegy","startegy","stategy"],"wordFamilyForms":[{"form":"strategy","partOfSpeech":"noun","example":"A good learning strategy combines practice, testing and regular rest.","pedagogicallyUseful":true},{"form":"strategic","partOfSpeech":"adjective","example":"The school made a strategic decision to spend more money on reading programmes.","pedagogicallyUseful":true,"altExample":"Every strategic plan needs clear goals, a timetable and a way of measuring success."},{"form":"strategically","partOfSpeech":"adverb","example":"The coach placed her best players strategically around the pitch.","pedagogicallyUseful":true,"altExample":"The signs were strategically placed so that visitors could find the exhibition easily."}],"masteryPassages":[{"passageId":"u6_15_strategy_passage_1","contextId":"u6_15_strategy_gap_1","text":"Instead of reading a new vocabulary list again and again, Elena tested herself with cards, grouped the words by topic and used each one in a sentence. This ____ took longer at first, but she remembered far more words by the end of the month.","answer":"strategy"},{"passageId":"u6_15_strategy_passage_2","contextId":"u6_15_strategy_gap_2","text":"The football club had lost six matches in a row. The new manager studied the results carefully and introduced a different ____: the team would defend deeply and attack quickly.","answer":"strategy"}],"contextDependentParaphrases":[],"wrongParaphrases":["sudden change of mind","last-minute decision","list of rules"],"misleadingDistractors":["a single action that is done without thinking","a rule that everyone must obey","a result that is reached after hard work"],"teacherNote":"A strategy is a carefully planned method, made up of several steps or decisions, for reaching a goal (a learning strategy). It is not a single action or trick. It is often followed by for or to: a strategy for learning, a strategy to reduce stress."}]'::jsonb,'["strategic","strategically"]'::jsonb,'["a learning strategy","develop a strategy","strategy for success"]'::jsonb,'live'),
('vocab_approach','approach','noun','a way of dealing with a task or problem','[{"senseId":"approach_1","meaning":"a way of dealing with a task or problem","acceptedParaphrases":["way of working","way of dealing with a task"],"masteryContexts":[{"contextId":"u6_16_approach_meaning","text":"A step-by-step approach to planning a long piece of writing makes the task seem less frightening.","meaning":"a method of dealing with a task","wrongMeanings":["a distance covered in one step","a rule about how to write a plan","a final answer to a difficult problem"]},{"contextId":"u6_16_approach_paraphrase","text":"The two scientists each took a very different approach to the same problem, but both reached the same result.","meaning":"a way of dealing with a problem","wrongMeanings":["a place where two paths meet","a test given at the end of the year","an argument between two scientists"]}],"situationDistractors":["The tourists took photographs of the old bridge and bought postcards.","He finished the last question, checked his name on the paper and left the hall.","Maya borrowed a pen from her neighbour and forgot to return it.","The chef chopped the onions and added them to the hot oil.","The pupils took their coats from the pegs and left the room in silence.","Some students arrived late because of the heavy traffic on the main road."],"gapDistractors":[{"contextId":"u6_16_approach_gap_1","answer":"approach","wrong":["uniform","playground","journey"]},{"contextId":"u6_16_approach_gap_2","answer":"approach","wrong":["journey","distance","building"]},{"contextId":"u6_16_approach_gap_3","answer":"approach","wrong":["building","rumour","invention"]}],"spellingErrors":["aproach","approch","apprach","approatch","appraoch","approche"],"masteryPassages":[{"passageId":"u6_16_approach_passage_1","contextId":"u6_16_approach_gap_1","text":"Some students try to write a long report in one session and feel exhausted by the end. A better ____ is to plan first, write one section at a time and leave time for checking.","answer":"approach"},{"passageId":"u6_16_approach_passage_2","contextId":"u6_16_approach_gap_2","text":"Two nurses cared for the same anxious patient. One spoke quickly and loudly, while the other used a slow and gentle ____, and only the second succeeded in calming the patient.","answer":"approach"}],"contextDependentParaphrases":[],"wrongParaphrases":["place for meetings","piece of equipment","list of questions"],"misleadingDistractors":["a distance between two places","a rule that must always be followed","a final answer to a problem"],"teacherNote":"Taught in its method sense: a way of dealing with a task or problem (a new approach to learning). The physical sense of moving closer (the approach of a train) is not taught. It is often followed by to: an approach to problem-solving."}]'::jsonb,'[]'::jsonb,'["a different approach","approach to learning","take a practical approach"]'::jsonb,'live'),
('vocab_revise','revise','verb','to study material again in order to prepare for an examination or to understand it better','[{"senseId":"revise_1","meaning":"to study material again in order to prepare for an examination or to understand it better","acceptedParaphrases":["go back over","prepare by studying"],"masteryContexts":[{"contextId":"u6_17_revise_meaning","text":"Maria plans to revise one subject each evening, starting with the topics she finds hardest.","meaning":"to study again to prepare for an examination","wrongMeanings":["to take an examination for the first time","to change a text to remove mistakes","to give a lesson to other students"]},{"contextId":"u6_17_revise_paraphrase","text":"Before the driving theory test, Karim used a mobile app to revise road signs during his bus journey.","meaning":"to study material again so that you remember it","wrongMeanings":["to learn road signs for the first time","to correct mistakes in a printed sign","to teach road signs to a friend"]}],"situationDistractors":["The editor crossed out a long paragraph and rewrote the opening sentence of the article.","On the first day of term, the new pupils learned the names of their teachers.","He took the test on Monday and received his result by email on Friday.","The clerk stamped each form and placed it in a wooden tray.","A tourist asked for directions to the station and thanked the stranger.","The teacher handed back the marked tests at the end of the lesson."],"gapDistractors":[{"contextId":"u6_17_revise_gap_1","answer":"revise","wrong":["argue","invent","complain"]},{"contextId":"u6_17_revise_gap_2","answer":"revise","wrong":["argue","compete","travel"]},{"contextId":"u6_17_revise_gap_3","answer":"revise","wrong":["avoid","hide","delete"]}],"spellingErrors":["revize","revice","revies","reviese","revisse","rivise"],"masteryPassages":[{"passageId":"u6_17_revise_passage_1","contextId":"u6_17_revise_gap_1","text":"The exam is in three weeks, so Jun has made a timetable. Every evening, he will ____ one subject, working through his notes and then answering questions from past papers.","answer":"revise"},{"passageId":"u6_17_revise_passage_2","contextId":"u6_17_revise_gap_2","text":"Memory research shows that students remember more when they ____ a topic several times over a few weeks than when they study it once for many hours. Each return visit makes the material easier to recall.","answer":"revise"}],"contextDependentParaphrases":[],"wrongParaphrases":["hand back","give out","write down"],"misleadingDistractors":["to change a text so that it contains fewer mistakes","to learn a topic for the first time","to take an examination at the end of a course"],"teacherNote":"Taught in the British exam-study sense: to study material again to prepare for an examination or to understand it better (revise for a test). The sense of editing a document is not taught here."}]'::jsonb,'[]'::jsonb,'["revise for an exam","revise a topic","revise regularly"]'::jsonb,'live'),
('vocab_forecast','forecast','verb','to say what is likely to happen in the future, using the information available','[{"senseId":"forecast_1","meaning":"to say what is likely to happen in the future, using the information available","acceptedParaphrases":["make an informed prediction about","say what is likely to happen"],"masteryContexts":[{"contextId":"u6_18_forecast_meaning","text":"Analysts forecast that online sales will double over the next five years because more people now shop on their phones.","meaning":"to say what will probably happen using information","wrongMeanings":["to guess the result without any information","to warn people about something that has happened","to explain why a result happened"]},{"contextId":"u6_18_forecast_paraphrase","text":"Using records from the past forty years, scientists can forecast how much the sea level will rise by the end of the century.","meaning":"to predict the future using evidence","wrongMeanings":["to describe how the sea has changed","to guess a number without any records","to measure the sea level on a beach"]}],"situationDistractors":["Nobody remembered the name of the captain who won the cup twenty years ago.","The farmer woke before dawn and fed the animals before breakfast.","She guessed the colour of the card in his hand and laughed when she was wrong.","The shop assistant wrapped the present and tied it with a red ribbon.","Ravi remembered the number of the bus but forgot where to get off.","The class repeated the new words after the teacher, one by one."],"gapDistractors":[{"contextId":"u6_18_forecast_gap_1","answer":"forecast","wrong":["cause","deny","remember"]},{"contextId":"u6_18_forecast_gap_2","answer":"forecast","wrong":["celebrate","copy","hide"]},{"contextId":"u6_18_forecast_gap_3","answer":"forecast","wrong":["spend","sell","remove"]}],"spellingErrors":["forcast","forecest","foracast","forekast","forecasst","fourcast"],"wordFamilyForms":[{"form":"forecast","partOfSpeech":"verb","example":"Scientists can forecast the weather several days ahead with growing accuracy.","pedagogicallyUseful":true},{"form":"forecaster","partOfSpeech":"noun","example":"The weather forecaster warned that heavy snow would arrive by midnight.","pedagogicallyUseful":true,"altExample":"A good forecaster explains how certain the prediction is, not only what will happen."},{"form":"forecasting","partOfSpeech":"noun","example":"Accurate forecasting depends on good data and careful analysis.","pedagogicallyUseful":true,"altExample":"Banks rely on careful forecasting to decide how much money to lend next year."}],"masteryPassages":[{"passageId":"u6_18_forecast_passage_1","contextId":"u6_18_forecast_gap_1","text":"Using satellite images and records from the past century, meteorologists can ____ the weather for the next seven days with a high degree of accuracy. Their statements are not guesses; they are based on measurable evidence.","answer":"forecast"},{"passageId":"u6_18_forecast_passage_2","contextId":"u6_18_forecast_gap_2","text":"The tourist board wants to ____ how many visitors will arrive next summer. To do this, it is studying booking figures from previous years and the latest information on flight prices.","answer":"forecast"}],"contextDependentParaphrases":[],"wrongParaphrases":["write a long report on","ask a direct question about","give a clear warning about"],"misleadingDistractors":["to guess something without looking at any information","to warn people about a danger that has already happened","to explain why something happened in the past"],"teacherNote":"Taught as a verb: to say what is likely to happen in the future using the information available (forecast the weather, forecast sales). A forecast is based on evidence, so it is different from a guess."}]'::jsonb,'["forecaster","forecasting"]'::jsonb,'["forecast the weather","forecast sales","accurately forecast"]'::jsonb,'live'),
('vocab_interfere','interfere','verb','to get in the way of something so that it cannot work or progress properly','[{"senseId":"interfere_1","meaning":"to get in the way of something so that it cannot work or progress properly","acceptedParaphrases":["get in the way","disturb the work of others"],"masteryContexts":[{"contextId":"u6_19_interfere_meaning","text":"Mobile phones can interfere with sleep if teenagers use them in bed late at night.","meaning":"to get in the way of something so that it does not work well","wrongMeanings":["to help something to work more smoothly","to prevent something from being stolen","to replace something that has broken"]},{"contextId":"u6_19_interfere_paraphrase","text":"The coach asked parents not to interfere during training, because the players needed to listen to one voice.","meaning":"to become involved in a way that disrupts something","wrongMeanings":["to give a clear and useful instruction","to cheer loudly for a team","to take part in a game as a player"]}],"situationDistractors":["The nurse took the patient’s temperature and wrote it on the chart.","Hana offered to carry her grandmother’s shopping and walked her to the front door.","The pupils sang a song together and then returned to their desks.","The pupils tidied their desks and left their bags by the door.","A neighbour watered the plants while the family were away on holiday.","The team trained for an hour before sunset and then went home."],"gapDistractors":[{"contextId":"u6_19_interfere_gap_1","answer":"interfere","wrong":["agree","cope","argue"]},{"contextId":"u6_19_interfere_gap_2","answer":"interfere","wrong":["deal","agree","cooperate"]},{"contextId":"u6_19_interfere_gap_3","answer":"interfere","wrong":["compete","agree","deal"]}],"spellingErrors":["interfear","interfer","intefere","interfeer","intarfere","interfeare"],"masteryPassages":[{"passageId":"u6_19_interfere_passage_1","contextId":"u6_19_interfere_gap_1","text":"Many teenagers say that they can study and watch a series at the same time. However, research suggests that the programme can ____ with their memory, so they learn less than they expect.","answer":"interfere"},{"passageId":"u6_19_interfere_passage_2","contextId":"u6_19_interfere_gap_2","text":"A good tutor gives hints rather than answers. If the tutor were to ____ every time a student made a mistake, the student would never learn how to solve a problem independently.","answer":"interfere"}],"contextDependentParaphrases":[],"wrongParaphrases":["stay out of sight","keep a safe distance","make way for others"],"misleadingDistractors":["to help someone to finish a job more quickly","to ask a question to check understanding","to join a team after the work has started"],"teacherNote":"Taught in the sense of getting involved in a way that prevents or disrupts something. It is often followed by with (interfere with sleep, interfere with learning) and sometimes by in (interfere in other people’s business). It is not the same as help."}]'::jsonb,'[]'::jsonb,'["interfere with sleep","interfere with learning","interfere in a decision"]'::jsonb,'live'),
('vocab_distract','distract','verb','to take someone’s attention away from what they should be thinking about or doing','[{"senseId":"distract_1","meaning":"to take someone’s attention away from what they should be thinking about or doing","acceptedParaphrases":["take attention away from","make it hard to pay attention"],"masteryContexts":[{"contextId":"u6_20_distract_meaning","text":"Bright posters on every wall can distract young children from the lesson.","meaning":"to take attention away from what you should be doing","wrongMeanings":["to give information about what to do","to make someone feel sleepy in lessons","to hide the lesson from young pupils"]},{"contextId":"u6_20_distract_paraphrase","text":"During the exam, a student was asked to leave because he kept trying to distract the candidate sitting next to him.","meaning":"to take someone’s attention away from their work","wrongMeanings":["to help someone to finish their work","to copy someone’s answers carelessly","to give someone extra time to work"]}],"situationDistractors":["The class listened carefully while the guest speaker described her experience as a pilot.","He wrote the date in the margin and underlined the title of the chapter.","The examiner collected the papers and counted them twice.","The chemistry teacher poured two clear liquids into a glass and waited for the colour to change.","Rita drank some water and carried on writing the last paragraph.","The cyclist stopped at the red light and waited for it to turn green."],"gapDistractors":[{"contextId":"u6_20_distract_gap_1","answer":"distract","wrong":["mislead","embarrass","photograph"]},{"contextId":"u6_20_distract_gap_2","answer":"distract","wrong":["follow","hire","insult"]},{"contextId":"u6_20_distract_gap_3","answer":"distract","wrong":["excuse","protect","prevent"]}],"spellingErrors":["distrct","distrack","disstract","distracct","destract","distarct"],"wordFamilyForms":[{"form":"distract","partOfSpeech":"verb","example":"Loud music can distract students who are trying to read.","pedagogicallyUseful":true},{"form":"distraction","partOfSpeech":"noun","example":"A mobile phone on the desk is a constant distraction during revision.","pedagogicallyUseful":true},{"form":"distracting","partOfSpeech":"adjective","example":"The noise from the building site was so distracting that nobody could think.","pedagogicallyUseful":true},{"form":"distracted","partOfSpeech":"adjective","example":"Students who feel distracted often miss important instructions.","pedagogicallyUseful":true}],"masteryPassages":[{"passageId":"u6_20_distract_passage_1","contextId":"u6_20_distract_gap_1","text":"The library has a rule that phones must be switched off. Even a quiet vibration can ____ people who are reading, and it may take several minutes for them to find their place again.","answer":"distract"},{"passageId":"u6_20_distract_passage_2","contextId":"u6_20_distract_gap_2","text":"Chen likes to work with music playing, but he chooses songs without words. Lyrics, he says, ____ him from the task because he starts to listen to the story.","answer":"distract"}],"contextDependentParaphrases":[],"wrongParaphrases":["give attention to","pay a visit to","take a message from"],"misleadingDistractors":["to make someone feel angry about their work","to help someone to remember a fact","to stop someone from entering a room"],"teacherNote":"Taught as a verb: to take someone’s attention away from what they should be concentrating on (distract students, distract from the task). It differs from interfere: distract affects attention, while interfere affects how something works or progresses."}]'::jsonb,'["distraction","distracting","distracted"]'::jsonb,'["distract attention","distract from the task","easily distract"]'::jsonb,'live')
